CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.risks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  risk_id TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  category TEXT,
  likelihood INT DEFAULT 3,
  impact INT DEFAULT 3,
  risk_score NUMERIC GENERATED ALWAYS AS (likelihood * impact) STORED,
  status TEXT DEFAULT 'identified',
  priority TEXT,
  workspace_id UUID,
  tenant_id TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(risk_id)
);

CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.risk_appetite_config (
  appetite_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID,
  appetite_name TEXT,
  overall_score NUMERIC DEFAULT 50,
  status TEXT DEFAULT 'active',
  review_cycle TEXT DEFAULT 'annual',
  next_review TIMESTAMPTZ,
  tenant_id TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(workspace_id)
);

CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.risk_scoring_models (
